Section FindA2.
  Context {fx : FPState}.
  Context {AC : AllocCeiling}.
  Variable L : Layout.
  Variable MI : MallocIface ASEGS L.
  Variables (NS : Z) (V : Type) (nval : mem -> Z -> V -> Prop).
  Hypothesis nval_agree : forall M M' p v, nval M p v -> agree_on M M' (p + 20) (NS - 20) -> 0 < p -> p + NS <= 2 ^ 47 -> nval M' p v.
  Variable rom : word -> option byte.
  Variables (A : AS MI) (M0 : mem) (obj bl bc keyp key sp0 k0 : Z) (ents : list (Z * (Z * V))) (ret : word).
  Hypothesis U0 : umapx MI NS nval A M0 obj bl bc ents.
  Hypothesis Hkey0 : cell4 ASEGS M0 keyp key.
  Hypothesis Hkp0 : 0 < keyp.
