  Definition atBB (R R' : bvmap 5 word) : Prop :=
    aonlyTS R R' /\ getr R' 10%bv = Z_to_bv 64 obj /\ getr R' 12%bv = Z_to_bv 64 bc /\ getr R' 13%bv = Z_to_bv 64 SHBASE
    /\ getr R' 14%bv = Z_to_bv 64 key /\ getr R' 15%bv = Z_to_bv 64 (hmod key bc)
    /\ getr R' 11%bv = popcwA (Z_to_bv 64 bc) /\ getr R' 2%bv = Z_to_bv 64 (sp0 - 16) /\ getr R' 1%bv = ret.

  Ltac runA R kk scr :=
    let E := fresh "E" in let HR := fresh "HR" in let HK := fresh "HK" in let Hpc := fresh "Hpc" in
    pose (E := Eseed R [Z_to_bv 64 obj; Z_to_bv 64 keyp; Z_to_bv 64 bc; Z_to_bv 64 key; Z_to_bv 64 k0; Z_to_bv 64 sp0; ret]);
    assert (HR : regs_ok E srA R) by
      (apply regs_ok_srs; [apply regs_ok_seed|];
       repeat (apply Forall_cons; [cbn [fst snd]; split; [intros X; discriminate X | evs; assumption] |]); apply Forall_nil);
    assert (HK : know_ok ASEGS E M0 (KNA kk scr)) by
      (kn_eval; unfold know_ok; apply Forall_cons; [kentry_tac|]; apply Forall_cons; [kentry_tac|];
       apply Forall_cons; [first [kentry_tac | eapply (kshadow E M0 (EVar 33) keyp k0 (EVar 36)); [evs; reflexivity | lia | lia | evs; reflexivity | exact Hk0]]|];
       know_tac);
    assert (Hpc : forall b : bool, branch_taken BC_LTU (edenot E (ELit 1)) (edenot E popcA) = b ->
                  sc_denot ASEGS M0 E (SCBr b BC_LTU (ELit 1) popcA)) by (intros b Hb; exact Hb);
    xrun HR HK 100%nat STOPS scr 50%N;
    [ split_scs; try sc_auto1; try sc_shdj; try sc_dj;
      try (apply Hpc; rewrite popcA_env; evs; rewrite branch_ltu_lit_l by lia; bool_lia);
      try sc_slow
    | match goal with Hm : msteps _ _ _ |- _ =>
        rewrite M1_eq in Hm by (evs; rewrite ?v_addi_Z by lia; first [reflexivity | f_equal; lia]) end ].

  Ltac finA idx_tac :=
    match goal with HR' : regs_ok ?E' _ ?R', Hms : msteps _ _ (mkst _ _ _ _) |- _ =>
    let AO := fresh "AO" in let PC := fresh "PC" in
    assert (AO : aonlyTS _ R') by (eapply aonlyTS_of_syms; [exact HR'| vm_cast_no_check (@eq_refl bool true)]);
    assert (PC : getr R' 11%bv = popcwA (Z_to_bv 64 bc)) by (exact (eq_trans (HR' 11%bv) (popcA_env E')));
    let G10 := fresh "G" in rreg HR' 10%bv G10; let G12 := fresh "G" in rreg HR' 12%bv G12;
    let G13 := fresh "G" in rreg HR' 13%bv G13; let G14 := fresh "G" in rreg HR' 14%bv G14;
    let G15 := fresh "G" in rreg HR' 15%bv G15; let G2 := fresh "G" in rreg HR' 2%bv G2;
    let G1 := fresh "G" in rreg HR' 1%bv G1;
    let G15' := fresh "G" in assert (G15' : getr R' 15%bv = Z_to_bv 64 (hmod key bc)) by (rewrite G15; idx_tac);
    let G2' := fresh "G" in assert (G2' : getr R' 2%bv = Z_to_bv 64 (sp0 - 16)) by (rewrite G2; apply w_addm; lia);
    exact (ex_intro _ R' (conj Hms (conj AO (conj G10 (conj G12 (conj G13 (conj G14 (conj G15' (conj PC (conj G2' G1))))))))))
    end.

