      (kn_eval; unfold know_ok; apply Forall_cons; [kentry_tac|]; apply Forall_cons; [kentry_tac|];
       apply Forall_cons; [first [kentry_tac | eapply (kshadow E M0 (EVar 33) keyp k0 (EVar 36)); [evs; reflexivity | lia | lia | evs; reflexivity | exact Hk0]]|];
       know_tac);
    xrun HR HK 100%nat STOPS scr 50%N;
    [ split_scs; try sc_auto1; try sc_shdj; try sc_dj; try sc_slow
    | match goal with Hm : msteps _ _ _ |- _ =>
        rewrite M1_eq in Hm by (evs; rewrite ?v_addi_Z by lia; first [reflexivity | f_equal; lia]) end ].

  Ltac finA0 :=
    match goal with HR' : regs_ok ?E' _ ?R', Hms : msteps _ _ (mkst _ _ _ _) |- _ =>
    let AO := fresh "AO" in
    assert (AO : aonlyTS _ R') by (eapply aonlyTS_of_syms; [exact HR'| vm_cast_no_check (@eq_refl bool true)]);
    let G10 := fresh "G" in rreg HR' 10%bv G10; let G2 := fresh "G" in rreg HR' 2%bv G2;
    let G1 := fresh "G" in rreg HR' 1%bv G1;
    let G2' := fresh "G" in assert (G2' : getr R' 2%bv = Z_to_bv 64 sp0) by (rewrite G2; rewrite ?w_addm, ?w_add by lia; f_equal; lia);
    exact (ex_intro _ R' (conj Hms (conj AO (conj G10 (conj G2' G1)))))
    end.

  Lemma blkA0 : forall R,
    getr R 10%bv = Z_to_bv 64 obj -> getr R 11%bv = Z_to_bv 64 keyp -> getr R 2%bv = Z_to_bv 64 sp0 -> getr R 1%bv = ret ->
    bc = 0 -> exists R', msteps ASEGS (st R FIND M0) (st R' RET1 M1) /\ aonlyTS R R'
      /\ getr R' 10%bv = Z_to_bv 64 0 /\ getr R' 2%bv = Z_to_bv 64 sp0 /\ getr R' 1%bv = ret.
Proof.
