  Definition KNB : list kentry := [KWord (SA (EVar 37) 8) 8 (EVar 38)].
  Definition KNBx (pc : Z) (sr : list expr) (scr : scripts) : list kentry := kn_fix 20 STOPS scr pc sr KNB 50.

  Lemma kra_ok : forall E, ev E 37 = Z_to_bv 64 (sp0 - 16) -> ev E 38 = ret ->
    kentry_ok ASEGS E M1 (KWord (SA (EVar 37) 8) 8 (EVar 38)).
Proof.
