  Ltac kB_tac := first [ kentry_tac | eapply kra_ok; evs; reflexivity ].
  Ltac knowB_tac :=
    lazymatch goal with
    | |- know_ok _ _ _ _ => unfold know_ok; knowB_tac
    | |- Forall _ [] => constructor
    | |- Forall _ (_ :: _) => constructor; [kB_tac | knowB_tac]
    end.

  Definition srB : list expr :=
    srs sr_id [(10%bv, EVar 32); (11%bv, EVar 33); (12%bv, EVar 34); (13%bv, ELit SHBASE); (14%bv, EVar 35); (15%bv, EVar 36);
               (2%bv, EVar 37); (1%bv, EVar 38)].
  Definition SCR_B_b0 := SCR [true] [EVar 40; EVar 41; EVar 42] [].
  Definition SCR_B_q0 := SCR [false; true] [EVar 40; EVar 41; EVar 42] [].
  Definition SCR_B_m := SCR [false; false; true] [EVar 40; EVar 41; EVar 42] [].
  Definition SCR_B_p := SCR [false; false; false] [EVar 40; EVar 41; EVar 42] [].

  Definition atLoop (R R' : bvmap 5 word) (q bcx : Z) : Prop :=
    aonlyTS R R' /\ getr R' 10%bv = Z_to_bv 64 q /\ getr R' 12%bv = Z_to_bv 64 bcx /\ getr R' 13%bv = Z_to_bv 64 SHBASE
    /\ getr R' 14%bv = Z_to_bv 64 key /\ getr R' 15%bv = Z_to_bv 64 (hmod key bc) /\ getr R' 16%bv = sxw key
    /\ getr R' 2%bv = Z_to_bv 64 (sp0 - 16) /\ getr R' 1%bv = ret.
  Definition atRet (R R' : bvmap 5 word) (r : Z) : Prop :=
    aonlyTS R R' /\ getr R' 10%bv = Z_to_bv 64 r /\ getr R' 2%bv = Z_to_bv 64 sp0 /\ getr R' 1%bv = ret.

  Lemma blkB : forall R (pw b q0 : Z),
    getr R 10%bv = Z_to_bv 64 obj -> getr R 11%bv = Z_to_bv 64 pw -> getr R 12%bv = Z_to_bv 64 bc ->
    getr R 13%bv = Z_to_bv 64 SHBASE -> getr R 14%bv = Z_to_bv 64 key -> getr R 15%bv = Z_to_bv 64 (hmod key bc) ->
    getr R 2%bv = Z_to_bv 64 (sp0 - 16) -> getr R 1%bv = ret ->
    0 <= pw < 2 ^ 64 -> bc <> 0 ->
    cell8 ASEGS M1 (bl + 8 * hmod key bc) b -> 0 <= b -> b + 8 <= 2 ^ 47 -> (b <> 0 -> cell8 ASEGS M1 b q0) -> (b <> 0 -> gz M1 b 8) ->
    exists R',
      ((b = 0 \/ q0 = 0) /\ msteps ASEGS (st R BB_PC M1) (st R' RET1 M1) /\ atRet R R' 0)
      \/ (b <> 0 /\ q0 <> 0 /\ 2 <= pw /\ msteps ASEGS (st R BB_PC M1) (st R' LM_PC M1) /\ atLoop R R' q0 bc)
      \/ (b <> 0 /\ q0 <> 0 /\ pw < 2 /\ msteps ASEGS (st R BB_PC M1) (st R' LP_PC M1) /\ atLoop R R' q0 (bc - 1)).
